import fs from 'node:fs';
import zlib from 'node:zlib';

const file = process.argv[2];
const mode = process.argv[3] || 'summary';
const buf = fs.readFileSync(file);
const magic = Buffer.from([0x28, 0xb5, 0x2f, 0xfd]);
const frames = [];
let pos = 0;
while (true) {
  const idx = buf.indexOf(magic, pos);
  if (idx === -1) break;
  frames.push(idx);
  pos = idx + 4;
}
const out = [];
for (let i = 0; i < frames.length; i++) {
  const start = frames[i];
  const end = i + 1 < frames.length ? frames[i + 1] : buf.length;
  try {
    out.push(zlib.zstdDecompressSync(buf.subarray(start, end)).toString('utf8'));
  } catch (e) {
    // fallthrough: try to end at next frame
  }
}
const text = out.join('\n');
fs.writeFileSync(file + '.decoded.jsonl', text);
console.log('frames=' + frames.length + ' decodedBytes=' + text.length);
const lines = text.split('\n').filter(Boolean);
console.log('lines=' + lines.length);
console.log('---last 3 events type---');
for (const l of lines.slice(-3)) {
  try { const o = JSON.parse(l); console.log(o.type || o.kind, JSON.stringify(o).slice(0, 200)); } catch { console.log('RAW', l.slice(0, 200)); }
}

import fs from 'node:fs';

const lines = fs.readFileSync(process.argv[2], 'utf8').split('\n').filter(Boolean);
const userMsgs = [];
const errs = [];
const calls = [];
let compactions = 0;
for (const l of lines) {
  let o;
  try { o = JSON.parse(l); } catch { continue; }
  const t = o.type || '';
  const d = o.data || {};
  if (t === 'user/message' || (t === 'message' && d.message?.role === 'user')) {
    const m = d.message || d;
    const c = typeof m.content === 'string' ? m.content : JSON.stringify(m.content);
    userMsgs.push({ seq: o.seq, text: c.slice(0, 3000) });
  }
  if (/error|fail|abort|retry/i.test(t)) errs.push({ seq: o.seq, type: t, s: JSON.stringify(d).slice(0, 600) });
  if (t === 'compaction' || /compact/i.test(t)) compactions++;
  if (t === 'tool/call') {
    let a = {};
    try { a = JSON.parse(d.arguments || '{}'); } catch {}
    calls.push({ seq: o.seq, step: d.step, turn: d.turn, name: d.name, arg: (a.command || a.file_path || a.pattern || a.query || a.description || '').slice(0, 260) });
  }
}
console.log('=== USER MESSAGES (' + userMsgs.length + ') ===');
for (const u of userMsgs) console.log('[' + u.seq + '] ' + u.text.slice(0, 1500) + '\n---');
console.log('=== ERRORS (' + errs.length + ') ===');
for (const e of errs.slice(-25)) console.log('[' + e.seq + '] ' + e.type + ' :: ' + e.s);
console.log('=== CALLS (' + calls.length + ') last 40 ===');
for (const c of calls.slice(-40)) console.log('[' + c.seq + '] t' + c.turn + 's' + c.step + ' ' + c.name + ' :: ' + c.arg);

